import {drawJerseySeams} from './wardrobe-detail.js';
export function drawJerseyArtwork(ctx,num,name,color){ctx.clearRect(0,0,512,640);ctx.save();const shape=[[-.22,.4],[-.4,.28],[-.33,.03],[-.22,.11],[-.22,-.43],[0,-.46],[.22,-.43],[.22,.11],[.33,.03],[.4,.28],[.22,.4],[.1,.4],[0,.29],[-.1,.4]];ctx.beginPath();shape.forEach(([x,y],i)=>{const xx=(x+.4)/.8*512,yy=(.43-y)/.9*640;if(i)ctx.lineTo(xx,yy);else ctx.moveTo(xx,yy);});ctx.closePath();ctx.clip();ctx.fillStyle=color;ctx.fillRect(0,0,512,640);for(let x=0;x<512;x++){const fold=Math.sin(x*.085)*.35+Math.sin(x*.021)*.65;ctx.fillStyle=fold>0?'rgba(255,244,235,'+(fold*.10)+')':'rgba(39,0,11,'+(-fold*.16)+')';ctx.fillRect(x,0,1,640);}ctx.strokeStyle=color==='#f2ce21'?'#171a1b':color==='#dedaca'?'#7e2234':'#f0e9df';ctx.lineWidth=6;for(const side of[-1,1])for(let j=0;j<3;j++){ctx.beginPath();ctx.moveTo(256+side*(113+j*10),26);ctx.lineTo(256+side*(153+j*10),112);ctx.stroke();}ctx.strokeStyle=color==='#f2ce21'?'#171a1b':color==='#dedaca'?'#7e2234':'#eadfd5';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(199,25);ctx.quadraticCurveTo(256,105,313,25);ctx.stroke();drawJerseySeams(ctx,color==='#dedaca');ctx.fillStyle=color==='#f2ce21'?'#171a1b':color==='#dedaca'?'#7e2234':'#f6f2e9';ctx.textAlign='center';ctx.font='bold 22px Arial';ctx.fillText(color==='#f2ce21'?'BORUSSIA DORTMUND':'FC BAYERN MÜNCHEN',256,150,265);ctx.font='bold 210px Bahnschrift,Arial';ctx.fillText(String(num),256,379,245);ctx.font='bold 31px Arial';ctx.fillText(name,256,449,265);ctx.font='13px Arial';ctx.fillText(color==='#f2ce21'?'BORUSSIA VERBINDET':'MIA SAN MIA',256,515);ctx.restore();}
